('pkg1a065fe566bc84owj', 'sv1a065fe566bpv68yt', 'BM', '', 'BM004', 'BM004', 'BM004A', 'Electrical contact burns: Low voltage - without part of limb / limb loss; Includes % TBSA skin grafted, flap cover, Surgical procedures are required for deep burns that are not amenable to heal with dressings alone.', 45000, 'Tier1(X)', 0, '', '', ''),
('pkg1a065fe566b66rums', 'sv1a065fe566bpv68yt', 'BM', '', 'BM004', 'BM004', 'BM004B', 'Electrical contact burns: Low voltage - with part of limb / limb loss; Includes % TBSA skin grafted, flap cover, follow-up dressings Amputation etc. as deemed necessary; Surgical procedures are required for deep burns that are not amenable to heal with dressings alone.', 60000, 'Tier1(X)', 0, '', '', ''),
